1	export type Scenario = {
2	  customer: { yearsWithMHPCO: number };
3	  steps: { op: string; items: { type: string }[] }[];
4	};
5	
6	export type ScenarioResult = {
7	  results: { premium: number }[];
8	};
9	
10	const PROCESSING_FEE = 5;
11	
12	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
13	
14	const BASE_PREMIUMS: Record<string, number> = {
15	  sword: 100,
16	  amulet: 60,
17	  staff: 80,
18	  potion: 40,
19	  rune: 25,
20	};
21	
22	// Percentages stay in integer percent points: multiply first, divide by 100
23	// last. A float multiplier such as `base * 1.1` yields 110.00000000000001 for
24	// a sword and breaks the ceil.
25	const percentOf = (amount: number, percent: number): number =>
26	  (amount * percent) / 100;
27	
28	const quote = (items: { type: string }[]): number => {
29	  const policyBase = items.reduce(
30	    (sum, item) => sum + BASE_PREMIUMS[item.type],
31	    0,
32	  );
33	
34	  const firstInsuranceSurcharge = percentOf(
35	    policyBase,
36	    FIRST_INSURANCE_SURCHARGE_PERCENT,
37	  );
38	
39	  // Rounding is in the MHPCO's favour: premiums round up.
40	  const premiumBeforeFee = Math.ceil(policyBase + firstInsuranceSurcharge);
41	
42	  return premiumBeforeFee + PROCESSING_FEE;
43	};
44	
45	export const runScenario = (scenario: Scenario): ScenarioResult => ({
46	  results: scenario.steps.map((step) => ({ premium: quote(step.items) })),
47	});
